def constant_loop():
    total = 0
    for i in range(10):
        total += i
    return total

def complex_o1(x, y):
    z = x + y
    w = x * y
    if z > w:
        return z - w
    else:
        return w - z

def constant_matrix_mult(m1, m2):
    res = [[0, 0], [0, 0]]
    for i in range(2):
        for j in range(2):
            for k in range(2):
                res[i][j] += m1[i][k] * m2[k][j]
    return res

def div_by_two(n):
    count = 0
    while n > 1:
        n //= 2
        count += 1
    return count

def power_of_two(n):
    if n <= 0: return False
    while n > 1:
        if n % 2 != 0: return False
        n //= 2
    return True

def div_by_three(n):
    steps = 0
    while n > 1:
        n = n // 3
        steps += 1
    return steps

def sqrt_binary_search(n):
    if n < 0: return -1
    low, high = 0, n
    ans = -1
    while low <= high:
        mid = (low + high) // 2
        if mid * mid <= n:
            ans = mid
            low = mid + 1
        else:
            high = mid - 1
    return ans

def gcd_log(a, b):
    while b > 0:
        a, b = b, a % b
    return a

def div_by_four(n):
