        steps += 1
    return steps

def search_in_rotated_array(arr, target):
    l, r = 0, len(arr) - 1
    while l <= r:
        mid = (l + r) // 2
        if arr[mid] == target: return mid
        if arr[l] <= arr[mid]:
            if arr[l] <= target < arr[mid]: r = mid - 1
            else: l = mid + 1
        else:
            if arr[mid] < target <= arr[r]: l = mid + 1
            else: r = mid - 1
    return -1

def power_of_three(n):
    if n <= 0: return False
    while n % 3 == 0:
        n //= 3
    return n == 1

def binary_search_float(target, low, high, tol):
    while high - low > tol:
        mid = (low + high) / 2.0
        if mid * mid * mid < target: low = mid
        else: high = mid
    return (low + high) / 2.0

def half_step_reduction(val):
    steps = 0
