        val = val * 0.5
        steps += 1
    return steps

def binary_search_recursive(arr, low, high, x):
    if high >= low:
        mid = (high + low) // 2
        if arr[mid] == x: return mid
        elif arr[mid] > x: return binary_search_recursive(arr, low, mid - 1, x)
        else: return binary_search_recursive(arr, mid + 1, high, x)
    return -1

