def binary_search_closest(arr, target):
    n = len(arr)
    if target <= arr[0]: return arr[0]
    if target >= arr[n - 1]: return arr[n - 1]
    i, j = 0, n
    while i < j:
        mid = (i + j) // 2
        if arr[mid] == target: return arr[mid]
        if target < arr[mid]:
            if mid > 0 and target > arr[mid - 1]:
                return arr[mid - 1] if target - arr[mid - 1] < arr[mid] - target else arr[mid]
            j = mid
        else:
            if mid < n - 1 and target < arr[mid + 1]:
                return arr[mid] if target - arr[mid] < arr[mid + 1] - target else arr[mid + 1]
            i = mid + 1
    return arr[i]

