def binary_insert_all(arr):
    res = []
    for x in arr:
        l, r = 0, len(res)
        while l < r:
            mid = (l + r) // 2
            if res[mid] < x: l = mid + 1
            else: r = mid
        res.insert(l, x)
    return res

def three_way_partition_sort(arr):
    if len(arr) <= 1: return arr
    p = arr[0]
    less = [x for x in arr[1:] if x < p]
    greater = [x for x in arr[1:] if x >= p]
    return three_way_partition_sort(less) + [p] + three_way_partition_sort(greater)

