def merge_intervals(intervals):
    if not intervals: return []
    s = sorted(intervals, key=lambda x: x[0])
    res = [s[0]]
    for current in s[1:]:
        prev = res[-1]
        if current[0] <= prev[1]: prev[1] = max(prev[1], current[1])
        else: res.append(current)
    return res

def find_closest_elements_sort(arr, k, x):
