    count = 0
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            if arr[i] > arr[j]: count += 1
    return count

def find_max_submatrix_sum_naive(matrix):
    n = len(matrix)
    max_sum = 0
    for i in range(n):
        for j in range(n):
            current = 0
            for x in range(i, n):
                for y in range(j, n):
                    current += matrix[x][y]
            max_sum = max(max_sum, current)
    return max_sum

def search_in_2d_grid(grid, val):
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == val: return r, c
    return -1, -1

def element_frequencies_quadratic(arr):
    res = {}
    for x in arr:
        count = 0
        for y in arr:
            if x == y: count += 1
        res[x] = count
    return res

def compute_similarity_score(arr1, arr2):
    score = 0
    for x in arr1:
        for y in arr2:
            if x == y: score += 1
    return score

def selection_sort_strings(words):
    n = len(words)
    for i in range(n):
        min_idx = i
        for j in range(i+1, n):
            if len(words[j]) < len(words[min_idx]): min_idx = j
        words[i], words[min_idx] = words[min_idx], words[i]
    return words

def remove_duplicates_nested(arr):
    res = []
    for x in arr:
        found = False
        for y in res:
            if x == y: found = True; break
        if not found: res.append(x)
    return res

def find_closest_pair(arr):
    min_diff = float('inf')
    res = None
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            diff = abs(arr[i] - arr[j])
            if diff < min_diff:
                min_diff = diff
                res = (arr[i], arr[j])
    return res

def print_times_table(n):
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            print(f'{i*j:4}', end='')
        print()

def contains_duplicate_subgrid(matrix):
    n = len(matrix)
    for r1 in range(n):
        for c1 in range(n):
            for r2 in range(n):
                for c2 in range(n):
                    if (r1, c1) != (r2, c2) and matrix[r1][c1] == matrix[r2][c2]:
                        return True
    return False

def count_smaller_elements_nested(arr):
    res = []
    for i in range(len(arr)):
        count = 0
        for j in range(len(arr)):
            if arr[j] < arr[i]: count += 1
        res.append(count)
    return res

def print_inverted_triangle(n):
    for i in range(n, 0, -1):
        for j in range(i):
            print('*', end='')
        print()

def fibonacci_naive(n):
    if n <= 1: return n
    return fibonacci_naive(n - 1) + fibonacci_naive(n - 2)

def coin_change_recursive(coins, amount, index):
    if amount == 0: return 1
    if amount < 0 or index >= len(coins): return 0
    return coin_change_recursive(coins, amount - coins[index], index) + coin_change_recursive(coins, amount, index + 1)

def knapsack_01_recursive(weights, values, capacity, n):
    if n == 0 or capacity == 0: return 0
    if weights[n-1] > capacity: return knapsack_01_recursive(weights, values, capacity, n-1)
    return max(values[n-1] + knapsack_01_recursive(weights, values, capacity-weights[n-1], n-1), knapsack_01_recursive(weights, values, capacity, n-1))

def subsets_sum_target(arr, target, index):
    if target == 0: return 1
    if index >= len(arr): return 0
    return subsets_sum_target(arr, target - arr[index], index + 1) + subsets_sum_target(arr, target, index + 1)

def subset_sum_exists(arr, n, target):
    if target == 0: return True
    if n == 0: return False
    if arr[n-1] > target: return subset_sum_exists(arr, n-1, target)
    return subset_sum_exists(arr, n-1, target) or subset_sum_exists(arr, n-1, target-arr[n-1])

def climb_stairs_naive(n):
    if n <= 1: return 1
    return climb_stairs_naive(n - 1) + climb_stairs_naive(n - 2)

def climb_stairs_three_steps(n):
    if n < 0: return 0
    if n == 0: return 1
    return climb_stairs_three_steps(n-1) + climb_stairs_three_steps(n-2) + climb_stairs_three_steps(n-3)

def rod_cutting_naive(price, n):
    if n <= 0: return 0
    max_val = -1
    for i in range(n):
        max_val = max(max_val, price[i] + rod_cutting_naive(price, n - i - 1))
    return max_val

def lev_distance_recursive(s1, s2, m, n):
    if m == 0: return n
    if n == 0: return m
    if s1[m-1] == s2[n-1]: return lev_distance_recursive(s1, s2, m-1, n-1)
    return 1 + min(lev_distance_recursive(s1, s2, m, n-1), lev_distance_recursive(s1, s2, m-1, n), lev_distance_recursive(s1, s2, m-1, n-1))

def partitions_count(n, m):
    if n == 0: return 1
    if n < 0 or m == 0: return 0
    return partitions_count(n - m, m) + partitions_count(n, m - 1)

def wildcard_match_recursive(pattern, text, p_idx, t_idx):
    if p_idx == len(pattern): return t_idx == len(text)
    if pattern[p_idx] == '*':
        return (wildcard_match_recursive(pattern, text, p_idx + 1, t_idx) or
                (t_idx < len(text) and wildcard_match_recursive(pattern, text, p_idx, t_idx + 1)))
    if t_idx < len(text) and (pattern[p_idx] == '?' or pattern[p_idx] == text[t_idx]):
        return wildcard_match_recursive(pattern, text, p_idx + 1, t_idx + 1)
    return False

def minimum_partition_difference(arr, n, sum_calculated, sum_total):
    if n == 0: return abs((sum_total - sum_calculated) - sum_calculated)
    return min(minimum_partition_difference(arr, n - 1, sum_calculated + arr[n - 1], sum_total),
               minimum_partition_difference(arr, n - 1, sum_calculated, sum_total))

def fibonacci_three(n):
    if n <= 0: return 0
    if n == 1: return 1
    return fibonacci_three(n-1) + fibonacci_three(n-2) + fibonacci_three(n-3)

def subset_sum_count(arr, index, current_sum, target):
    if current_sum == target: return 1
    if index >= len(arr): return 0
    return subset_sum_count(arr, index + 1, current_sum + arr[index], target) + subset_sum_count(arr, index + 1, current_sum, target)

def naive_recursive_matching(p, s):
    if not p: return not s
    first_match = bool(s) and p[0] in {s[0], '.'}
    if len(p) >= 2 and p[1] == '*':
        return naive_recursive_matching(p[2:], s) or (first_match and naive_recursive_matching(p, s[1:]))
    return first_match and naive_recursive_matching(p[1:], s[1:])

def binary_strings_no_consecutive_ones(n):
    if n == 1: return 2
    if n == 2: return 3
    return binary_strings_no_consecutive_ones(n - 1) + binary_strings_no_consecutive_ones(n - 2)

def coin_change_naive_ways(coins, m, n):
    if n == 0: return 1
    if n < 0: return 0
    if m <= 0: return 0
    return coin_change_naive_ways(coins, m - 1, n) + coin_change_naive_ways(coins, m, n - coins[m - 1])

def grid_unique_paths_naive(m, n):
    if m == 1 or n == 1: return 1
    return grid_unique_paths_naive(m - 1, n) + grid_unique_paths_naive(m, n - 1)

def edit_distance_naive(s1, s2, i, j):
    if i == 0: return j
    if j == 0: return i
    if s1[i-1] == s2[j-1]: return edit_distance_naive(s1, s2, i-1, j-1)
    return 1 + min(edit_distance_naive(s1, s2, i, j-1), edit_distance_naive(s1, s2, i-1, j), edit_distance_naive(s1, s2, i-1, j-1))

def knapsack_01_with_profit(wt, val, w, n):
    if n == 0 or w == 0: return 0
    if wt[n - 1] > w: return knapsack_01_with_profit(wt, val, w, n - 1)
    return max(val[n - 1] + knapsack_01_with_profit(wt, val, w - wt[n - 1], n - 1),
               knapsack_01_with_profit(wt, val, w, n - 1))

def count_binary_trees_naive(n):
    if n <= 1: return 1
    sum_val = 0
    for i in range(1, n + 1):
        sum_val += count_binary_trees_naive(i - 1) * count_binary_trees_naive(n - i)
    return sum_val

def combination_sum_naive(candidates, target, index):
    if target == 0: return 1
    if target < 0 or index >= len(candidates): return 0
    return combination_sum_naive(candidates, target - candidates[index], index) + combination_sum_naive(candidates, target, index + 1)

def count_subsets_with_given_difference(arr, n, diff, s1, total):
    if n == 0:
        s2 = total - s1
        return 1 if s1 - s2 == diff else 0
    return (count_subsets_with_given_difference(arr, n - 1, diff, s1 + arr[n - 1], total) +
            count_subsets_with_given_difference(arr, n - 1, diff, s1, total))

def longest_common_subsequence_naive(X, Y, m, n):
    if m == 0 or n == 0: return 0
    if X[m - 1] == Y[n - 1]: return 1 + longest_common_subsequence_naive(X, Y, m - 1, n - 1)
    return max(longest_common_subsequence_naive(X, Y, m, n - 1),
               longest_common_subsequence_naive(X, Y, m - 1, n))
